solution:
public class Multiplicador {
    static int multiplicar(int a, int b) { return a * b; }
    static double multiplicar(double a, double b) { return a * b; }
    static String multiplicar(String t, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(t);
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(multiplicar(4, 5));
        System.out.println(multiplicar(2.5, 3.0));
        System.out.println(multiplicar("Java", 3));
    }
}

template:
public class Temperatura {
    // TODO: Two methods called convertir
    // convertir(double, String origen) -> String
    // convertir(double, String origen, String destino) -> double

    public static void main(String[] args) {
        System.out.println(convertir(100, "C"));
        System.out.printf("%.2f%n", convertir(100, "C", "F"));
        System.out.printf("%.2f%n", convertir(0, "C", "K"));
    }
}

solution:
public class Temperatura {
    static String convertir(double g, String o) {
        double c = o.equalsIgnoreCase("C") ? g : o.equalsIgnoreCase("F") ? (g-32)*5.0/9.0 : g-273.15;
        return String.format("%.1f C = %.1f F = %.1f K", c, (c*9.0/5.0)+32, c+273.15);
    }
    static double convertir(double g, String o, String d) {
        double c = o.equalsIgnoreCase("C") ? g : o.equalsIgnoreCase("F") ? (g-32)*5.0/9.0 : g-273.15;
        return d.equalsIgnoreCase("C") ? c : d.equalsIgnoreCase("F") ? (c*9.0/5.0)+32 : c+273.15;
    }
    public static void main(String[] args) {
        System.out.println(convertir(100, "C"));
        System.out.printf("%.2f%n", convertir(100, "C", "F"));
        System.out.printf("%.2f%n", convertir(0, "C", "K"));
    }
}
